/**
 * @name Path traversal in file operations
 * @description Using user-controlled paths without validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-injection
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() = "name" and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled data"

/**
 * @name Code injection via compile/exec
 * @description Using compile/exec with user-controlled input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-compile-exec
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // File read operations
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("io").getMember("open").getACall() or
        call = API::moduleImport("os").getMember("environ").getASubscript().getAValueReachableFromSource()
      ) and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("compile").getACall() or
        call = API::builtin("exec").getACall() or
        call = API::builtin("eval").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "file or environment variable"

/**
 * @name SQL injection
 * @description SQL query constructed from user input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"
